#!/bin/sh
storage_tools_menu(){ while :; do c=$(ui_menu 'Storage and filesystem tools' 'Usage analysis, cleanup, mounts, links, and benchmarks.' usage 'Filesystem usage' largest 'Largest files and directories' duplicates 'Duplicate-file scan' broken 'Broken symlink scan' mounts 'Mount management center' bind 'Create bind-mount helper' cleanup 'Cache and temporary cleanup' benchmark 'Filesystem benchmark' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in usage) run_capture Usage sh -c 'df -h; printf "\nInodes:\n"; df -i';; largest) d=$(ui_input Largest 'Path' "$CURRENT_HOME") || continue; run_capture Largest sh -c "du -a '$d' 2>/dev/null | sort -rn | head -100";; duplicates) d=$(ui_input Duplicates 'Path' "$CURRENT_HOME") || continue; if have fdupes; then run_capture Duplicates fdupes -r "$d"; else run_capture Duplicates sh -c "find '$d' -type f -exec sha256sum {} + 2>/dev/null | sort | awk 'p==\$1{print prev;print} {p=\$1;prev=\$0}'"; fi;; broken) d=$(ui_input Symlinks 'Path' "$CURRENT_HOME") || continue; run_capture Symlinks find "$d" -xtype l -print;; mounts) mount_manager_menu;; bind) src=$(ui_input Bind 'Source' '') || continue; dst=$(ui_input Bind 'Destination' '') || continue; out="$CURRENT_HOME/bin/mount-bind-$(basename "$dst")"; write_file "$out" 755 "#!/bin/sh\nmkdir -p '$dst'\nmount --bind '$src' '$dst'"; ui_msg Bind "Created $out";; cleanup) ui_yesno Cleanup 'Remove common user caches and stale temporary files?' && { rm -rf "$CURRENT_HOME/.cache"/* 2>/dev/null || true; find /tmp -type f -mtime +7 -delete 2>/dev/null || true; package_clean 2>/dev/null || true; };; benchmark) d=$(ui_input Benchmark 'Directory' "$CURRENT_HOME") || continue; run_capture Benchmark sh -c "f='$d/.ish-aok-io-test'; dd if=/dev/zero of=\"\$f\" bs=1M count=32 conv=fsync 2>&1; dd if=\"\$f\" of=/dev/null bs=1M 2>&1; rm -f \"\$f\"";; back) return;; esac; done; }
